import 'package:mcp_client/mcp_client.dart';

void main() async {
  final config = McpClient.simpleConfig(
    name: 'Example Client',
    version: '1.0.0',
  );
  final transportConfig = TransportConfig.stdio(
    command: 'npx',
    arguments: ['-y', '@modelcontextprotocol/server-filesystem', '/path/to/dir'],
  );
  final clientResult = await McpClient.createAndConnect(
    config: config,
    transportConfig: transportConfig,
  );
  final client = clientResult.fold((c) => c, (error) => throw error);
  client.disconnect();
}
